def _make_main_verify_internal_task(store, *, head_sha: str = "feedfacecafe") -> DbTask:
    task = store.add("System alert: local main integration verify", task_type="internal", skip_learnings=True)
    assert task.id is not None
    task.status = "completed"
    task.completed_at = datetime.now(UTC)
    task.review_verify_head_sha = head_sha
    store.update(task)
    return task


def _make_completed_watch_merge_task(
    store,
    prompt: str,
    *,
    branch: str,
    tags: tuple[str, ...] | None = None,
    trigger_source: str | None = None,
) -> DbTask:
    task = store.add(prompt, task_type="implement", tags=tags, trigger_source=trigger_source)
    assert task.id is not None
    task.status = "completed"
    task.completed_at = datetime.now(UTC)
    task.branch = branch
    task.has_commits = True
    store.update(task)
    store.set_merge_status(task.id, "unmerged")
    return task


def _candidate_verify_check(
    tmp_path: Path,
    *,
    status: str = "passed",
    classification: str = "pass",
    tree_fingerprint: str = "fp-candidate",
    head_sha: str = "candidate-head",
    failure: str | None = None,
    failing_phase: str | None = None,
) -> CandidateIntegrationVerifyCheck:
    return CandidateIntegrationVerifyCheck(
        evidence=CandidateIntegrationVerifyEvidence(
            gate_enabled=True,
            verify_command="./bin/tests",
            verify_timeout_seconds=300,
            verify_timeout_grace_seconds=5.0,
            environment_identity=None,
            tree_fingerprint=tree_fingerprint,
            head_sha=head_sha,
            verify_status=status,
            verify_exit_status="0" if status == "passed" else "1",
            failure=failure,
            failing_phase=failing_phase,
            reviewed_branch="main",
            working_directory=str(tmp_path),
            captured_at=datetime.now(UTC),
        ),
        classification=classification,
        merges_halted=status != "passed",
        remediation=None,
        verify_runs=1,
    )


def _watch_blocker_finding(finding_id: str) -> ReviewFinding:
    return ReviewFinding(
        id=finding_id,
        severity="BLOCKER",
        title=f"Blocker {finding_id}",
        body="Body",
        evidence="Evidence",
        impact="Impact",
        fix_or_followup="Fix it",
        tests="Run tests",
        open_state_citation="still open",
    )


def _watch_capped_review_output(*finding_ids: str, verdict: str = "CHANGES_REQUESTED") -> str:
    sections = ["## Review", "", f"Verdict: {verdict}", "", "## Blockers", ""]
    for finding_id in finding_ids or ("B1",):
        sections.extend(
            [
                f"### {finding_id} Blocker {finding_id}",
                "Evidence: Evidence",
                "Impact: Impact",
                "Required fix: Fix it",
                "Required tests: Run tests",
                "Open-state citation: still open",
                "",
            ]
        )
    return "\n".join(sections)


def _watch_followup_finding(finding_id: str) -> ReviewFinding:
    return ReviewFinding(
        id=finding_id,
        severity="FOLLOWUP",
        title=f"Follow-up {finding_id}",
        body="Body",
        evidence="Evidence",
        impact="Impact",
        fix_or_followup="Follow up",
        tests="Run tests",
        open_state_citation="still open",
    )


def _persist_watch_merge_finalization_proof(
    store: SqliteTaskStore,
    *,
    action_family: str,
    impl: DbTask,
    review: DbTask,
    findings: tuple[ReviewFinding, ...],
    children: tuple[DbTask, ...],
    target_sha: str = "same-sha",
) -> None:
    assert impl.id is not None
    assert impl.branch is not None
    assert review.id is not None
    unit = store.resolve_merge_unit_for_task(impl.id)
    persist_merge_finalization_attempt_proof(
        store,
        action_family=action_family,  # type: ignore[arg-type]
        impl_task_id=impl.id,
        review_task_id=review.id,
        finding_ids=tuple(finding.id for finding in findings),
        child_task_ids=tuple(child.id for child in children if child.id is not None),
        source_branch=impl.branch,
        source_ref=impl.branch,
        source_ref_sha="source-sha",
        target_branch="main",
        previous_target_sha="target-before",
        promoted_target_sha=target_sha,
        merge_unit_id=unit.id if unit is not None else None,
    )


