def _seed_watch_deferred_blocker(
    store: SqliteTaskStore,
    *,
    blocker_tags: tuple[str, ...] = ("deferred-review-blocker",),
) -> Task:
    source = store.add("Merged max-cycle watch source", task_type="implement")
    store.mark_completed(source, has_commits=True, branch=f"feature/watch-max-cycle-source-{len(store.get_all())}")
    assert source.id is not None
    source_unit = store.resolve_merge_unit_for_task(source.id)
    assert source_unit is not None
    store.set_merge_unit_state(source_unit.id, "merged", merge_source=MERGE_SOURCE_MAX_CYCLES_DEFERRED)

    blocker = store.add(
        "Deferred watch blocker",
        task_type="implement",
        based_on=source.id,
        depends_on=source.id,
        tags=blocker_tags,
    )
    assert blocker.id is not None
    return blocker


def _make_watch_startup_git() -> Git:
    git = _make_watch_git()
    git.branch_exists.return_value = False  # type: ignore[attr-defined]
    return git


def _append_watch_config(tmp_path: Path, extra: str) -> None:
    config_path = tmp_path / "gza.yaml"
    config_path.write_text(config_path.read_text() + extra)


def _watch_args(tmp_path: Path, task_ids: list[str], **overrides: object) -> argparse.Namespace:
    defaults: dict[str, object] = {
        "project_dir": tmp_path,
        "task_ids": task_ids,
        "batch": 1,
        "poll": 1,
        "max_idle": None,
        "max_iterations": 10,
        "restart_failed": False,
        "restart_failed_batch": None,
        "max_resume_attempts": None,
        "dry_run": False,
        "show_skipped": False,
        "quiet": True,
        "yes": True,
        "resumed_reexec": False,
        "tags": None,
        "any_tag": False,
        "all_tags": False,
        "auto_restart_on_drift": True,
        "dispatch_mode": None,
        "recovery_slots": None,
        "watch_lease_token": None,
        "watch_projects": None,
        "watch_tags": None,
        "watch_all_tags": None,
        "watch_weights": None,
        "watch_strategy": None,
        "watch_config": None,
        "watch_state_dir": None,
    }
    defaults.update(overrides)
    return argparse.Namespace(**defaults)


def _wait_for_dispatch_start_from_store(store):
    return lambda **kwargs: (
        True,
        f"task {kwargs['task_id']} reached running state",
        store.get(str(kwargs["task_id"])),
    )


def test_watch_supervisor_cli_selectors_preserve_order_and_keyed_associations(tmp_path: Path) -> None:
    server_dir = tmp_path / "server"
    server_dir.mkdir()

    selection = resolve_watch_supervisor_selection(
        _watch_args(
            tmp_path,
            [],
            watch_projects=["core=.", "server=server"],
            watch_tags=["server=api", "core=release", "server=ops"],
            watch_all_tags=["server"],
            watch_weights=["core=2"],
            watch_strategy="weighted-round-robin",
        )
    )

    assert isinstance(selection, WatchSupervisorSelection)
    assert [project.key for project in selection.projects] == ["core", "server"]
    assert selection.strategy == "weighted-round-robin"
