    alpha_registry = MagicMock()
    alpha_registry.workers_dir = alpha_config.workers_path
    alpha_registry.list_all.return_value = [
        WorkerMetadata(
            worker_id="w-alpha",
            task_id=alpha_task.id,
            pid=os.getpid(),
            status="running",
        )
    ]
