def test_watch_long_phase_reporter_emits_start_busy_and_no_progress(tmp_path: Path) -> None:
    log_path = tmp_path / ".gza" / "watch.log"
    log = _WatchLog(log_path, quiet=True)
    reporter = _WatchLongPhaseReporter(log=log, threshold_seconds=60, interval_seconds=60)

    heartbeat = reporter.start("verify:unit", "gza-9026")
    heartbeat(
        LongPhaseProgress(
            elapsed_seconds=60,
            cpu_delta_seconds=58,
            output_bytes_delta=4096,
            output_lines_delta=412,
            no_progress=False,
        )
    )
    heartbeat(
        LongPhaseProgress(
            elapsed_seconds=120,
            cpu_delta_seconds=0,
            output_bytes_delta=0,
            output_lines_delta=0,
            no_progress=True,
        )
    )

    log_text = log_path.read_text()
    assert "START" in log_text
    assert "verify:unit gza-9026" in log_text
    assert "BUSY" in log_text
    assert "elapsed 1m00s cpu +58s out +412 lines" in log_text
    assert "elapsed 2m00s cpu +0s out +0 bytes (NO PROGRESS)" in log_text


def test_watch_log_emit_serializes_concurrent_writers(tmp_path: Path) -> None:
    log_path = tmp_path / ".gza" / "watch.log"
    log = _WatchLog(log_path, quiet=True)
    writer_count = 4
    lines_per_writer = 20
    barrier = threading.Barrier(writer_count)

    def emit_lines(writer_id: int) -> None:
        barrier.wait()
        for line_id in range(lines_per_writer):
            log.emit("BUSY", f"writer-{writer_id} line-{line_id}")

    threads = [threading.Thread(target=emit_lines, args=(idx,)) for idx in range(writer_count)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join(timeout=1.0)
        assert not thread.is_alive()

    lines = log_path.read_text().splitlines()
    assert len(lines) == writer_count * lines_per_writer
    for writer_id in range(writer_count):
        for line_id in range(lines_per_writer):
            assert sum(line.endswith(f"writer-{writer_id} line-{line_id}") for line in lines) == 1


