    heartbeat = watch_module._make_composite_long_phase_heartbeat(
        reporter.start("verify:main", "main"),
        FakeWorkerHeartbeat(),
    )

    assert heartbeat.seconds_until_next() == 0.25  # type: ignore[attr-defined]
