@pytest.mark.parametrize("gate", ["backoff", "no_progress"])
def test_watch_supervisor_recovery_preflight_rejects_parked_head_and_reuses_slot_until_gate_clears(
    tmp_path: Path,
    gate: str,
) -> None:
    runtime_a = _make_aggregate_runtime(tmp_path / f"project-a-{gate}", project_name="a")
    runtime_b = _make_aggregate_runtime(tmp_path / f"project-b-{gate}", project_name="b")
    failed_a = _add_failed_resume_row(runtime_a, f"A gated recovery {gate}")
    failed_b = _add_failed_resume_row(runtime_b, f"B recovery uses rejected slot {gate}")
    assert failed_a.id is not None
    assert failed_b.id is not None
    decision_a = _recovery_decision(failed_a, action="retry", reason_code=f"{gate}-retry")
    action_a = {"type": "retry", "description": f"{gate} retry"}
    entry_a = _recovery_entry(failed_a, action_type="retry", decision=decision_a)
    entry_a = replace(entry_a, advance_action=action_a)
    entry_b = _recovery_entry(failed_b, action_type="retry")
    candidate_a = ProjectDispatchCandidate(
        runtime_key=runtime_a.key,
        task=failed_a,
        lane="recovery",
        runtime_identity=runtime_a.runtime_identity,
        selection_mode="recovery_only",
        max_recovery_attempts=1,
        preview_entry=entry_a,
        owner_task=failed_a,
    )
    candidate_b = ProjectDispatchCandidate(
        runtime_key=runtime_b.key,
        task=failed_b,
        lane="recovery",
        runtime_identity=runtime_b.runtime_identity,
        selection_mode="recovery_only",
        max_recovery_attempts=1,
        preview_entry=entry_b,
        owner_task=failed_b,
    )
    progress_candidate = build_watch_progress_candidate(
        runtime_a.store,
        subject_task=failed_a,
        action=action_a,
        action_task=failed_a,
        failed_task=failed_a,
    )
    if gate == "backoff":
        runtime_a.store.upsert_watch_recovery_backoff(
            WatchRecoveryBackoff(
                subject_kind=progress_candidate.subject_kind,
                subject_id=progress_candidate.subject_id,
                action_type=progress_candidate.action_type,
                action_reason=progress_candidate.action_reason,
                subject_task_id=progress_candidate.subject_task_id,
                last_failure_task_id=failed_a.id,
                last_failure_reason="PROVIDER_UNAVAILABLE",
                last_failure_fingerprint="transient:retry:PROVIDER_UNAVAILABLE",
                streak=1,
                next_retry_at=datetime.now(UTC) + timedelta(minutes=10),
                updated_at=datetime.now(UTC),
            )
        )
    else:
        runtime_a.store.upsert_watch_progress_observation(
            WatchProgressObservation(
                subject_kind=progress_candidate.subject_kind,
                subject_id=progress_candidate.subject_id,
                action_type=progress_candidate.action_type,
                action_reason=progress_candidate.action_reason,
                subject_task_id=progress_candidate.subject_task_id,
                action_task_id=progress_candidate.action_task_id,
                action_task_status=progress_candidate.action_task_status,
                action_task_started_at=progress_candidate.action_task_started_at,
                action_task_running_pid=progress_candidate.action_task_running_pid,
                failed_task_id=progress_candidate.failed_task_id,
                recovery_task_id=progress_candidate.recovery_task_id,
                merge_unit_id=progress_candidate.merge_unit_id,
                merge_unit_state=progress_candidate.merge_unit_state,
                merge_unit_head_sha=progress_candidate.merge_unit_head_sha,
                evidence_fingerprint=progress_candidate.evidence_fingerprint,
                streak=2,
                parked_reason=WATCH_NO_PROGRESS_BACKSTOP_REASON,
                observed_at=datetime.now(UTC),
            )
        )

    dispatched: list[tuple[str, str]] = []

    def recovery_head(runtime: WatchProjectRuntime) -> ProjectDispatchCandidate | None:
        return candidate_a if runtime.key == "a" else candidate_b

    def settle_live(*, pending_starts: list[object], store: SqliteTaskStore, **_kwargs: object) -> list[object]:
        [settle_entry] = pending_starts
        task_id = getattr(settle_entry, "task_id")
        assert isinstance(task_id, str)
        owner_runtime = runtime_a if store is runtime_a.store else runtime_b
        _register_live_worker_for_task(owner_runtime.config, task_id, worker_id=f"w-{owner_runtime.key}-{task_id}")
        return _live_settle_results(pending_starts, store=store)

    with (
        patch.object(
            runtime_a,
            "recovery_dispatch_head",
            side_effect=lambda **_kwargs: recovery_head(runtime_a),
        ),
        patch.object(
            runtime_b,
            "recovery_dispatch_head",
            side_effect=lambda **_kwargs: recovery_head(runtime_b),
        ),
        patch("gza.cli.watch._settle_watch_dispatch_starts", side_effect=settle_live),
        patch("gza.cli.watch._spawn_background_worker", return_value=0),
        patch("gza.cli.watch._spawn_background_iterate", return_value=0),
    ):
        first_results = dispatch_watch_supervisor_lane_incrementally(
            [runtime_a, runtime_b],
            lane="recovery",
            limit=1,
            recovery_mode="recovery_only",
            max_recovery_attempts=1,
            strategy=create_watch_dispatch_strategy("round-robin", project_order=("a", "b")),
            launch_budget=SupervisorLaunchBudget([runtime_a, runtime_b], supervisor_batch=1),
        )

    dispatched.extend((result.runtime_key, result.status) for result in first_results)
    assert dispatched == [("a", "not_dispatchable"), ("b", "live")]

    if gate == "backoff":
        runtime_a.store.upsert_watch_recovery_backoff(
            WatchRecoveryBackoff(
                subject_kind=progress_candidate.subject_kind,
                subject_id=progress_candidate.subject_id,
                action_type=progress_candidate.action_type,
                action_reason=progress_candidate.action_reason,
                subject_task_id=progress_candidate.subject_task_id,
                last_failure_task_id=failed_a.id,
                last_failure_reason="PROVIDER_UNAVAILABLE",
                last_failure_fingerprint="transient:retry:PROVIDER_UNAVAILABLE",
                streak=1,
                next_retry_at=datetime.now(UTC) - timedelta(seconds=1),
                updated_at=datetime.now(UTC),
            )
        )
    else:
        clear_watch_progress_subject(runtime_a.store, subject_task=failed_a)
    runtime_a.begin_dispatch_pass()

    with (
        patch.object(runtime_a, "recovery_dispatch_head", return_value=candidate_a),
        patch("gza.cli.watch._settle_watch_dispatch_starts", side_effect=settle_live),
        patch("gza.cli.watch._spawn_background_worker", return_value=0),
        patch("gza.cli.watch._spawn_background_iterate", return_value=0),
    ):
        second_results = dispatch_watch_supervisor_lane_incrementally(
            [runtime_a],
            lane="recovery",
            limit=1,
            recovery_mode="recovery_only",
            max_recovery_attempts=1,
            strategy=create_watch_dispatch_strategy("project-priority", project_order=("a",)),
            launch_budget=SupervisorLaunchBudget([runtime_a], supervisor_batch=1),
        )

    assert [(result.runtime_key, result.status) for result in second_results] == [("a", "live")]


@pytest.mark.parametrize("claim_kind", ["running", "starting"])
def test_watch_supervisor_fleet_cycle_preserves_pre_direct_claim_when_budget_refresh_disables_runtime(
    tmp_path: Path,
    claim_kind: str,
) -> None:
    runtime_a = _make_aggregate_runtime(tmp_path / f"{claim_kind}-project-a", project_name="a")
    runtime_b = _make_aggregate_runtime(tmp_path / f"{claim_kind}-project-b", project_name="b")
    task_a = runtime_a.store.add(f"A has {claim_kind} worker before refresh failure", task_type="plan")
    task_b = runtime_b.store.add("B should not consume phantom slot", task_type="plan")
    assert task_a.id is not None
    assert task_b.id is not None
    candidate_b = _runtime_candidate(runtime_b, task_b, lane="pending")
    if claim_kind == "running":
        claimed_state = ProjectRuntimeReconcileResult(
            runtime_key="a",
            live_pids=frozenset(),
            running_task_ids=(task_a.id,),
            anonymous_worker_count=0,
            starting_worker_count=0,
            runtime_identity=runtime_a.runtime_identity,
        )
    else:
        claimed_state = ProjectRuntimeReconcileResult(
            runtime_key="a",
            live_pids=frozenset(),
            running_task_ids=(),
            anonymous_worker_count=0,
            starting_worker_count=1,
            starting_task_ids=(task_a.id,),
            starting_worker_ids=("worker-a-starting",),
            runtime_identity=runtime_a.runtime_identity,
        )
    empty_b_state = ProjectRuntimeReconcileResult(
        runtime_key="b",
        live_pids=frozenset(),
        running_task_ids=(),
        anonymous_worker_count=0,
        starting_worker_count=0,
        runtime_identity=runtime_b.runtime_identity,
    )
    selection = WatchSupervisorSelection(
        projects=(
            WatchSupervisorProjectSelector(
                key="a", ref=str(runtime_a.config.project_dir), path=runtime_a.config.project_dir
            ),
            WatchSupervisorProjectSelector(
                key="b", ref=str(runtime_b.config.project_dir), path=runtime_b.config.project_dir
            ),
        )
    )
    disabled: list[watch_module.ExecutionProjectDisabled] = []

    with (
        patch(
            "gza.cli.watch.construct_watch_project_runtimes",
            return_value=WatchSupervisorRuntimeConstruction(runtimes=(runtime_a, runtime_b)),
        ),
        patch.object(WatchProjectRuntime, "initialize_baseline", autospec=True, return_value=None),
        patch.object(
            WatchProjectRuntime,
            "analyze_cycle",
            autospec=True,
            side_effect=lambda runtime, **_kwargs: _runtime_analysis_with_pending_suppression(runtime),
        ),
        patch.object(
            WatchProjectRuntime,
            "run_direct_phase",
            autospec=True,
            side_effect=lambda runtime, **_kwargs: ProjectDirectResult(runtime_key=runtime.key, work_done=False),
        ),
        patch.object(
            runtime_a,
            "reconcile_runtime_state",
            side_effect=[claimed_state, sqlite3.OperationalError("database is locked")],
        ),
        patch.object(runtime_b, "reconcile_runtime_state", return_value=empty_b_state),
        patch.object(WatchProjectRuntime, "recovery_dispatch_head", autospec=True, return_value=None),
        patch.object(
            runtime_a,
            "pending_dispatch_head",
            side_effect=AssertionError("disabled runtime queried for pending dispatch"),
        ),
        patch.object(runtime_b, "pending_dispatch_head", return_value=candidate_b),
        patch.object(
            SupervisorLaunchBudget,
            "dispatch_pending_candidate",
            autospec=True,
            side_effect=AssertionError("pending dispatch consumed a phantom slot"),
        ),
    ):
        result, _lease_set = run_watch_supervisor_fleet_cycle(
            anchor_store=runtime_a.store,
            selection=selection,
            quiet=True,
            owner_token=None,
            existing_lease_set=None,
            batch=1,
            recovery_slots=0,
            recovery_mode="pending_only",
            max_recovery_attempts=1,
            max_iterations=1,
            dry_run=True,
            recovery_strategy=create_watch_dispatch_strategy("round-robin", project_order=("a", "b")),
            pending_strategy=create_watch_dispatch_strategy("round-robin", project_order=("a", "b")),
            emit_summary=False,
            runtime_state=WatchSupervisorRuntimeState(),
        )

    disabled.extend(item for item in result.disabled if item.selector_key == "a")
    assert [(item.selector_key, item.reason) for item in disabled] == [("a", "db_unavailable")]
    assert result.occupancy is not None
    if claim_kind == "running":
        assert result.occupancy.running == 1
        assert result.occupancy.starting == 0
    else:
        assert result.occupancy.running == 0
        assert result.occupancy.starting == 1
    assert result.occupancy.slots == 0
    assert result.dispatch_results.pending_results == ()


def test_watch_supervisor_recovery_lane_refreshes_selected_runtime_head_after_success(
    tmp_path: Path,
) -> None:
    runtime = _make_aggregate_runtime(tmp_path / "project-a", project_name="a")
    first = _runtime_candidate(runtime, runtime.store.add("First recovery", task_type="implement"), lane="recovery")
    second = _runtime_candidate(
        runtime, runtime.store.add("Refreshed recovery", task_type="implement"), lane="recovery"
    )
    budget = SupervisorLaunchBudget([runtime], supervisor_batch=2)
    dispatched: list[str] = []
    head_calls: list[str] = []

    def recovery_head(**_kwargs: object) -> ProjectDispatchCandidate | None:
        if not dispatched:
            head_calls.append("first-before-dispatch")
            return first
        head_calls.append("second-after-dispatch")
        return second

    def dispatch_recovery(
        selected_runtime: WatchProjectRuntime,
        candidate: ProjectDispatchCandidate,
        launch_budget: SupervisorLaunchBudget,
    ) -> ProjectDispatchResult:
        reservation = launch_budget.reserve(candidate)
        assert reservation is not None
        assert candidate.task.id is not None
        dispatched.append(candidate.task.id)
        _mark_runtime_task_live(selected_runtime, candidate.task.id)
        launch_budget.refresh_occupancy()
        return ProjectDispatchResult(
            runtime_key=selected_runtime.key,
            candidate=candidate,
            status="live",
            slot_consuming=True,
            work_done=True,
            task=selected_runtime.store.get(candidate.task.id),
        )

    with patch.object(runtime, "recovery_dispatch_head", side_effect=recovery_head):
        results = dispatch_watch_supervisor_lane_incrementally(
            [runtime],
            lane="recovery",
            limit=2,
            recovery_mode=None,
            max_recovery_attempts=1,
            strategy=create_watch_dispatch_strategy("project-priority", project_order=("a",)),
            launch_budget=budget,
            dispatch_candidate=dispatch_recovery,
        )

    assert [result.candidate.task.id for result in results] == [first.task.id, second.task.id]
    assert head_calls == ["first-before-dispatch", "second-after-dispatch"]
    assert dispatched == [first.task.id, second.task.id]


def test_watch_supervisor_donates_recovery_capacity_to_pending_after_recovery_heads_drain(
    tmp_path: Path,
) -> None:
    runtime = _make_aggregate_runtime(tmp_path / "project-a", project_name="a")
    recovery = _runtime_candidate(runtime, runtime.store.add("Only recovery", task_type="implement"), lane="recovery")
    pending = _runtime_candidate(
        runtime, runtime.store.add("Pending after recovery drain", task_type="plan"), lane="pending"
    )
    budget = SupervisorLaunchBudget([runtime], supervisor_batch=2)
    recovery_drained = False

    def recovery_head(**_kwargs: object) -> ProjectDispatchCandidate | None:
        return None if recovery_drained else recovery

    def pending_head(**_kwargs: object) -> ProjectDispatchCandidate | None:
        assert recovery_drained is True
        return pending

    def dispatch_recovery(
        selected_runtime: WatchProjectRuntime,
        candidate: ProjectDispatchCandidate,
        launch_budget: SupervisorLaunchBudget,
    ) -> ProjectDispatchResult:
        nonlocal recovery_drained
        reservation = launch_budget.reserve(candidate)
        assert reservation is not None
        assert candidate.task.id is not None
        _mark_runtime_task_live(selected_runtime, candidate.task.id)
        launch_budget.refresh_occupancy()
        recovery_drained = True
        return ProjectDispatchResult(
            runtime_key=selected_runtime.key,
            candidate=candidate,
            status="live",
            slot_consuming=True,
            work_done=True,
            task=selected_runtime.store.get(candidate.task.id),
        )

    with (
        patch.object(runtime, "recovery_dispatch_head", side_effect=recovery_head),
        patch.object(runtime, "pending_dispatch_head", side_effect=pending_head),
    ):
        lane_results = dispatch_watch_supervisor_lanes_incrementally(
            [runtime],
            recovery_slots_config=2,
            recovery_mode=None,
            max_recovery_attempts=1,
            recovery_strategy=create_watch_dispatch_strategy("project-priority", project_order=("a",)),
            pending_strategy=create_watch_dispatch_strategy("project-priority", project_order=("a",)),
            launch_budget=budget,
            dispatch_recovery_candidate=dispatch_recovery,
            dispatch_pending_candidate=lambda selected_runtime, candidate, _budget: ProjectDispatchResult(
                runtime_key=selected_runtime.key,
                candidate=candidate,
                status="dry_run",
                slot_consuming=False,
                work_done=True,
                dispatch_budget_consuming=True,
                task=candidate.task,
            ),
        )

    assert [result.candidate.task.id for result in lane_results.recovery_results] == [recovery.task.id]
    assert [result.candidate.task.id for result in lane_results.pending_results] == [pending.task.id]


@pytest.mark.parametrize("recovery_mode", [None, "recovery_only"])
def test_watch_supervisor_deferred_recovery_head_withholds_pending_capacity(
    tmp_path: Path,
    recovery_mode: Any,
) -> None:
    runtime = _make_aggregate_runtime(tmp_path / "project-a", project_name="a")
    failed = _add_failed_resume_row(runtime, "Recovery dry-run withholds pending capacity")
    recovery = runtime.recovery_dispatch_head(max_recovery_attempts=1, recovery_mode="recovery_only")
    assert recovery is not None
    assert recovery.task.id == failed.id
    pending = _runtime_candidate(runtime, runtime.store.add("Pending must wait", task_type="plan"), lane="pending")
    budget = SupervisorLaunchBudget([runtime], supervisor_batch=1, dry_run=True)
    pending_dispatches: list[str] = []

    with (
        patch.object(runtime, "recovery_dispatch_head", return_value=recovery),
        patch.object(runtime, "pending_dispatch_head", return_value=pending),
    ):
        lane_results = dispatch_watch_supervisor_lanes_incrementally(
            [runtime],
            recovery_slots_config=1,
            recovery_mode=recovery_mode,
            max_recovery_attempts=1,
            recovery_strategy=create_watch_dispatch_strategy("project-priority", project_order=("a",)),
            pending_strategy=create_watch_dispatch_strategy("project-priority", project_order=("a",)),
            launch_budget=budget,
            dispatch_pending_candidate=lambda selected_runtime, candidate, _budget: (
                pending_dispatches.append(str(candidate.task.id))
                or ProjectDispatchResult(
                    runtime_key=selected_runtime.key,
                    candidate=candidate,
                    status="dry_run",
                    slot_consuming=False,
                    work_done=True,
                    dispatch_budget_consuming=True,
                    task=candidate.task,
                )
            ),
        )

    assert [result.candidate.task.id for result in lane_results.recovery_results] == [recovery.task.id]
    assert lane_results.pending_results == ()
    assert pending_dispatches == []
    assert budget.virtual_dispatch_starts == 1
    assert budget.occupancy.slots == 0


