def test_watch_cycle_default_recovery_slot_caps_pending_implement_starts(tmp_path: Path) -> None:
    """One actionable recovery with batch 3 should leave room for only two pending implement starts."""
    setup_config(tmp_path)
    store = make_store(tmp_path)

    failed = store.add("Failed implement", task_type="implement")
    assert failed.id is not None
    failed.status = "failed"
    failed.failure_reason = "MAX_TURNS"
    failed.session_id = "sess-recovery-slot-cap"
    failed.completed_at = datetime.now(UTC)
    store.update(failed)

    pending_impls = [store.add(f"Pending implement {index}", task_type="implement") for index in range(4)]
    pending_ids = {task.id for task in pending_impls}

    config = Config.load(tmp_path)
    log = _WatchLog(tmp_path / ".gza" / "watch.log", quiet=True)

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli.watch._spawn_background_iterate", return_value=0) as spawn_iterate,
    ):
        result = _run_cycle(
            config=config,
            store=store,
            batch=3,
            max_iterations=10,
            dry_run=False,
            log=log,
            max_recovery_attempts=config.max_resume_attempts,
        )

    assert result.work_done is True
    assert spawn_iterate.call_count == 3
    recovery_calls = [call for call in spawn_iterate.call_args_list if call.args[2].based_on == failed.id]
    pending_calls = [call for call in spawn_iterate.call_args_list if call.args[2].id in pending_ids]
    assert len(recovery_calls) == 1
    assert len(pending_calls) == 2


def test_watch_cycle_executes_only_planned_recovery_ids_and_preserves_pending_slot(tmp_path: Path) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)
    config = Config.load(tmp_path)
    log_path = tmp_path / ".gza" / "watch.log"
    log = _WatchLog(log_path, quiet=True)

    first_failed = store.add("First failed implement", task_type="implement")
    second_failed = store.add("Second failed implement", task_type="implement")
    assert first_failed.id is not None
    assert second_failed.id is not None
    for task in (first_failed, second_failed):
        task.status = "failed"
        task.failure_reason = "PROVIDER_ERROR"
        task.completed_at = datetime.now(UTC)
        store.update(task)

    first_retry_child = store.add(
        first_failed.prompt, task_type="implement", based_on=first_failed.id, recovery_origin="retry"
    )
    second_retry_child = store.add(
        second_failed.prompt,
        task_type="implement",
        based_on=second_failed.id,
        recovery_origin="retry",
    )
    pending_plan = store.add("Pending plan", task_type="plan")
    assert first_retry_child.id is not None
    assert second_retry_child.id is not None
    assert pending_plan.id is not None

    first_row = LineageOwnerRow(
        owner_task=first_failed,
        members=(first_failed,),
        tree=None,
        lineage_status="actionable",
        next_action=None,
        next_action_reason="recovery",
        unresolved_tasks=(first_failed,),
        unresolved_leaf_summary=(),
        lifecycle_action_task=None,
        recovery_action_task=first_failed,
        recovery_leaf_task=first_failed,
    )
    second_row = LineageOwnerRow(
        owner_task=second_failed,
        members=(second_failed,),
        tree=None,
        lineage_status="actionable",
        next_action=None,
        next_action_reason="recovery",
        unresolved_tasks=(second_failed,),
        unresolved_leaf_summary=(),
        lifecycle_action_task=None,
        recovery_action_task=second_failed,
        recovery_leaf_task=second_failed,
    )
    first_decision = FailedRecoveryDecision(
        task_id=first_failed.id,
        action="retry",
        reason_code="retry_provider_error",
        reason_text="Retry first failed implementation",
        launch_mode="worker",
        attempt_index=1,
        attempt_limit=2,
        recovery_task_id=first_retry_child.id,
        reuse_existing=True,
    )
    second_decision = FailedRecoveryDecision(
        task_id=second_failed.id,
        action="retry",
        reason_code="retry_provider_error",
        reason_text="Retry second failed implementation",
        launch_mode="worker",
        attempt_index=1,
        attempt_limit=2,
        recovery_task_id=second_retry_child.id,
        reuse_existing=True,
    )
    precomputed_plan = _WatchCyclePlan(
        running_task_ids=(),
        anonymous_worker_count=0,
        pending_count=1,
        blocked_pending_count=0,
        running=0,
        effective_batch=2,
        slots=2,
        analysis=_WatchCycleAnalysis(
            target_branch="main",
            scope_gaps=(),
            owner_rows=(first_row, second_row),
            watch_read_context=RecoveryReadContext(),
            lifecycle_rows=(),
            recovery_rows=(first_row, second_row),
            recovery_lane_entry_by_failed_id={},
            action_plan=(),
            recovery_attention_rows=(),
            recovery_visible_skips=(),
            actionable_failed=(
                (
                    first_row,
                    first_failed,
                    first_decision,
                    {"type": "retry", "description": "Retry first"},
                    True,
                    first_failed,
                ),
                (
                    second_row,
                    second_failed,
                    second_decision,
                    {"type": "retry", "description": "Retry second"},
                    True,
                    second_failed,
                ),
            ),
            active_recovery_subject_ids=(),
        ),
    )

    def build_preview(*_args: object, **kwargs: object) -> DispatchPreview:
        include_recovery = bool(kwargs.get("include_recovery", True))
        if include_recovery:
            return DispatchPreview(
                entries=(
                    DispatchPreviewEntry(
                        lane="recovery",
                        task=first_failed,
                        owner_task=first_failed,
                        runnable=True,
                        worker_consuming=True,
                        decision=first_decision,
                        advance_action={"type": "retry"},
                        lineage_row=first_row,
                    ),
                    DispatchPreviewEntry(
                        lane="recovery",
                        task=second_failed,
                        owner_task=second_failed,
                        runnable=True,
                        worker_consuming=True,
                        decision=second_decision,
                        advance_action={"type": "retry"},
                        lineage_row=second_row,
                    ),
                    DispatchPreviewEntry(
                        lane="pending",
                        task=pending_plan,
                        runnable=True,
                        worker_consuming=True,
                    ),
                )
            )
        return DispatchPreview(
            entries=(
                DispatchPreviewEntry(
                    lane="pending",
                    task=pending_plan,
                    runnable=True,
                    worker_consuming=True,
                ),
            )
        )

    started_task_ids: list[str] = []

    def spawn_worker(
        _args: argparse.Namespace,
        _config: Config,
        *,
        task_id: str,
        **_kwargs: object,
    ) -> int:
        started_task_ids.append(task_id)
        return 0

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli.watch.Git", return_value=_make_watch_git()),
        patch("gza.cli.watch.build_dispatch_preview", side_effect=build_preview),
        patch("gza.cli.watch._prepare_task_for_immediate_execution", side_effect=lambda _config, task, **_kwargs: task),
        patch(
            "gza.cli.watch._spawn_background_iterate",
            side_effect=AssertionError("retry worker should stay on plain worker path"),
        ),
        patch(
            "gza.cli.watch._spawn_background_resume_worker",
            side_effect=AssertionError("retry worker should not use resume path"),
        ),
        patch("gza.cli.watch._spawn_background_worker", side_effect=spawn_worker),
        patch(
            "gza.cli.watch._settle_watch_dispatch_starts",
            side_effect=lambda *, pending_starts, **_kwargs: _live_settle_results(pending_starts, store=store),
        ),
    ):
        result = _run_cycle(
            config=config,
            store=store,
            batch=2,
            recovery_slots=1,
            max_iterations=10,
            dry_run=False,
            log=log,
            max_recovery_attempts=config.max_resume_attempts,
            precomputed_plan=precomputed_plan,
        )

    assert result.work_done is True
    assert started_task_ids == [first_retry_child.id, pending_plan.id]
    log_text = log_path.read_text()
    assert second_retry_child.id not in started_task_ids
    assert not any(
        line.split(maxsplit=2)[1] == "START" and second_retry_child.id in line for line in log_text.splitlines()
    )
    assert any(line.split(maxsplit=2)[1] == "START" and pending_plan.id in line for line in log_text.splitlines())


def test_watch_dispatch_preview_recovery_preflight_rebase_is_runnable_and_consumes_only_recovery_slot(
    tmp_path: Path,
) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)

    failed_impl = store.add("Failed implementation", task_type="implement")
    assert failed_impl.id is not None
    failed_impl.status = "failed"
    failed_impl.failure_reason = "MAX_STEPS"
    failed_impl.session_id = "sess-watch-recovery-preflight"
    failed_impl.completed_at = datetime.now(UTC)
    failed_impl.branch = "feature/watch-recovery-preflight"
    failed_impl.merge_status = "unmerged"
    failed_impl.has_commits = True
    failed_impl.num_steps_computed = 1
    store.update(failed_impl)

    pending_impl = store.add("Pending implement fallback", task_type="implement")
    assert pending_impl.id is not None

    config = Config.load(tmp_path)
    git = _make_watch_git()
    git.ref_exists = MagicMock(side_effect=lambda ref: ref == f"origin/{failed_impl.branch}")  # type: ignore[method-assign]
    git.rev_parse_if_exists = MagicMock(  # type: ignore[method-assign]
        side_effect=lambda ref: "target-tip" if ref == "main" else "branch-tip"
    )
    git.is_ancestor = MagicMock(  # type: ignore[method-assign]
        side_effect=lambda ancestor, descendant: (
            ancestor == "main" and descendant == f"origin/{failed_impl.branch}" and False
        )
    )
    preview = build_dispatch_preview(
        store,
        config=config,
        git=git,
        target_branch="main",
        tags=None,
        any_tag=True,
        max_recovery_attempts=config.max_resume_attempts,
    )
    recovery_entries = [entry for entry in preview.recovery_entries if entry.task.id == failed_impl.id]
    pending_entries = [entry for entry in preview.pending_entries if entry.task.id == pending_impl.id]

    assert len(recovery_entries) == 1
    assert recovery_entries[0].advance_action is not None
    assert recovery_entries[0].advance_action["type"] == "needs_rebase"
    assert recovery_entries[0].advance_action["rebase_parent_task_id"] == failed_impl.id
    assert recovery_entries[0].worker_consuming is True
    assert len(pending_entries) == 1

    plan = plan_watch_dispatch_entries(
        preview.runnable_entries,
        slots=1,
        recovery_slot_cap=config.watch.recovery_slots,
        selection_mode="default",
    )

    assert plan.recovery_worker_slots == 1
    assert plan.pending_slots == 0
    assert len(plan.entries) == 1
    assert plan.entries[0].task.id == failed_impl.id


def test_watch_cycle_dry_run_matches_shared_preview_dispatch_plan_order(tmp_path: Path) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)
    store._default_merge_target_cache = "main"  # noqa: SLF001 - avoid real git in unit test
    store._project_root = None  # noqa: SLF001 - avoid real git fallback in unit test

    failed = store.add("Failed implement", task_type="implement")
    assert failed.id is not None
    failed.status = "failed"
    failed.failure_reason = "MAX_TURNS"
    failed.session_id = "sess-preview-parity"
    failed.completed_at = datetime.now(UTC)
    store.update(failed)

    pending_plan = store.add("Pending plan", task_type="plan")
    pending_impl = store.add("Pending implement", task_type="implement")
    pending_plan_two = store.add("Pending plan two", task_type="plan")
    assert pending_plan.id is not None
    assert pending_impl.id is not None
    assert pending_plan_two.id is not None

    config = Config.load(tmp_path)
    log_path = tmp_path / ".gza" / "watch.log"

    preview = build_dispatch_preview(
        store,
        config=config,
        tags=None,
        any_tag=False,
        max_recovery_attempts=config.max_resume_attempts,
    )
    plan = plan_watch_dispatch_entries(
        preview.runnable_entries,
        slots=3,
        recovery_slot_cap=config.watch.recovery_slots,
        selection_mode="default",
    )

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli.watch._spawn_background_iterate", side_effect=AssertionError("dry-run should not spawn")),
        patch("gza.cli.watch._spawn_background_worker", side_effect=AssertionError("dry-run should not spawn")),
    ):
        result = _run_cycle(
            config=config,
            store=store,
            batch=3,
            max_iterations=10,
            dry_run=True,
            log=_WatchLog(log_path, quiet=True),
            max_recovery_attempts=config.max_resume_attempts,
        )

    assert result.work_done is True
    log_lines = log_path.read_text().splitlines()
    dispatched_ids: list[str] = []
    for line in log_lines:
        if "RECOVR" in line:
            dispatched_ids.append(failed.id)
        elif "START" in line and "[dry-run]" in line:
            for task_id in (pending_plan.id, pending_impl.id, pending_plan_two.id):
                if isinstance(task_id, str) and task_id in line:
                    dispatched_ids.append(task_id)
                    break
    assert dispatched_ids == [entry.task.id for entry in plan.entries]


def test_watch_cycle_executes_only_planned_recovery_entries_and_preserves_pending_slot(tmp_path: Path) -> None:
    setup_config(tmp_path)
    store = make_store(tmp_path)
    store._default_merge_target_cache = "main"  # noqa: SLF001 - avoid real git in unit test
    store._project_root = None  # noqa: SLF001 - avoid real git fallback in unit test

    recovery_one = store.add("Failed implement one", task_type="implement")
    assert recovery_one.id is not None
    recovery_one.status = "failed"
    recovery_one.failure_reason = "MAX_TURNS"
    recovery_one.session_id = "sess-first-recovery"
    recovery_one.completed_at = datetime(2026, 7, 1, 12, 0, 0, tzinfo=UTC)
    store.update(recovery_one)

    recovery_two = store.add("Failed implement two", task_type="implement")
    assert recovery_two.id is not None
    recovery_two.status = "failed"
    recovery_two.failure_reason = "MAX_TURNS"
    recovery_two.session_id = "sess-second-recovery"
    recovery_two.completed_at = datetime(2026, 7, 1, 12, 5, 0, tzinfo=UTC)
    store.update(recovery_two)

    pending_plan = store.add("Pending plan", task_type="plan")
    assert pending_plan.id is not None

    config = Config.load(tmp_path)
    log_path = tmp_path / ".gza" / "watch.log"
    real_plan_watch_dispatch_entries = plan_watch_dispatch_entries

    def fake_plan_watch_dispatch_entries(
        entries: tuple[DispatchPreviewEntry, ...],
        *,
        slots: int,
        recovery_slot_cap: int,
        selection_mode: str,
        include_pending: bool = True,
    ) -> WatchDispatchPlan:
        if selection_mode == "default":
            recovery_entries = [entry for entry in entries if entry.lane == "recovery"]
            pending_entries = [entry for entry in entries if entry.lane == "pending"]
            assert [entry.task.id for entry in recovery_entries] == [recovery_one.id, recovery_two.id]
            assert [entry.task.id for entry in pending_entries] == [pending_plan.id]
            return WatchDispatchPlan(
                entries=(recovery_entries[1], pending_entries[0]),
                recovery_worker_slots=1,
                pending_slots=1,
            )
        return real_plan_watch_dispatch_entries(
            entries,
            slots=slots,
            recovery_slot_cap=recovery_slot_cap,
            selection_mode=selection_mode,
            include_pending=include_pending,
        )

    with (
        patch("gza.cli._common.reconcile_in_progress_tasks"),
        patch("gza.cli._common.prune_terminal_dead_workers"),
        patch("gza.cli.watch.plan_watch_dispatch_entries", side_effect=fake_plan_watch_dispatch_entries),
        patch("gza.cli.watch._spawn_background_iterate", side_effect=AssertionError("dry-run should not spawn")),
        patch("gza.cli.watch._spawn_background_worker", side_effect=AssertionError("dry-run should not spawn")),
    ):
        result = _run_cycle(
            config=config,
            store=store,
            batch=2,
            max_iterations=10,
            dry_run=True,
            log=_WatchLog(log_path, quiet=True),
            max_recovery_attempts=config.max_resume_attempts,
        )

    assert result.work_done is True
    log_lines = log_path.read_text().splitlines()
    recovery_lines = [line for line in log_lines if "RECOVR" in line]
    assert any(recovery_two.id in line for line in recovery_lines)
    assert all(recovery_one.id not in line for line in recovery_lines)
    assert any("START" in line and str(pending_plan.id) in line and "[dry-run]" in line for line in log_lines)


