    git.current_branch = MagicMock(return_value="topic")  # type: ignore[method-assign]
    git.rev_parse_if_exists = MagicMock(  # type: ignore[method-assign]
        side_effect=lambda ref: target_head if ref == "refs/heads/main" else None
    )

    log.begin_cycle()
    _finalize_main_verify_attention(
        log=log,
        state=persisted_state,
        now=datetime(2026, 6, 24, 12, 13, tzinfo=UTC),
        git=git,
        target_branch="main",
    )
    _emit_cycle_attention_summary(log)

    # The roundup repeats the per-task message; the log current attention state
    # exposes the same active message for non-log consumers.
    messages = log.visible_attention_messages()
    assert any(
        "main verify remediation exhausted for phase:functional after 2/2 attempts; human intervention required"
        in message
        for message in messages
    )
    assert any("feedfacecafe" not in message for message in messages)
    assert any("merges halted" not in message for message in messages)
    assert git.rev_parse_if_exists.call_args_list == [call("refs/heads/main")]


